 return <LegacyProfileLayout rows={profiles} reviews={reviews} links={links} syncReady={syncReady} assignments={assignments} onReconcile={onReconcile} reviewSchemaReady={reviewSchemaReady} active={active} onReturn={onReturn} onEditAssignment={onEditAssignment} onResolvePending={onResolvePending} onRetireAssignment={onRetireAssignment} onEditLegacy={onEditLegacy} onLegacyCustody={onLegacyCustody} onLoss={onLoss} onChangeCondition={onChangeCondition} showSourceNote={false} showReviewSummary={false}/>;
