 const [date,setDate]=useState('');
 const [notes,setNotes]=useState(''); const [extraDetails,setExtraDetails]=useState<string[]>(['']);
 const composedNotes=[notes.trim(),...extraDetails.map((value,index)=>value.trim()?`Detalles${index?' '+(index+1):''}: ${value.trim()}`:'')].filter(Boolean).join('\n');
 const detailFields=<div className="extra-details-fields"><b>Detalles adicionales</b>{extraDetails.map((value,index)=><label key={index}>Detalle {index+1}<input maxLength={500} value={value} onChange={event=>setExtraDetails(current=>current.map((item,itemIndex)=>itemIndex===index?event.target.value:item))} placeholder="Ej.: Roja, con batería, accesorio…"/></label>)}<button type="button" className="secondary small-button" onClick={()=>setExtraDetails(current=>[...current,''])}><Plus size={14}/> Agregar otro detalle</button></div>;
 const [confirmed,setConfirmed]=useState(false);
 const available=allUnits.filter(unit=>unit.lifecycle==='active'&&unit.condition!=='out_of_service'&&unit.condition!=='review'&&!(unit.assignments||[]).some(a=>a.status==='active'||a.status==='pending_review')&&((unit.ownership==='station')||(unit.ownership==='firefighter'&&unit.owner_firefighter_id===row.firefighter_id)));
 const selectedUnit=available.find(unit=>unit.id===unitId);
 const chosenOwnership=mode==='existing'?selectedUnit?.ownership:ownership;
 const chosenCondition=mode==='existing'?selectedUnit?.condition:condition;
 const chosenType=mode==='existing'?selectedUnit?.typeName:typeName.trim();
 async function submit(event:FormEvent){event.preventDefault();if(!supabase||!person||!date||!confirmed)return;await save(async()=>{const {data,error}=await supabase!.rpc('reconcile_legacy_item',{p_legacy_row_id:row.id,p_existing_unit_id:mode==='existing'?unitId||null:null,p_type_name:mode==='new'?typeName.trim():null,p_ownership:mode==='new'?ownership:null,p_condition:mode==='new'?condition:null,p_brand:brand||null,p_size:size||null,p_delivered_on:date,p_notes:composedNotes||null,p_confirmed:true});if(error)throw error;if(!data?.already_linked&&(!data?.equipment_unit_id||!data?.assignment_id))throw new Error('Supabase no devolvió una unidad y asignación verificables.');},chosenOwnership==='station'?'Unidad vinculada al bombero; se reflejará como asignada en Inventario.':'Equipo personal vinculado; aparece en la ficha y permanece fuera del stock del cuartel.');}
