function ImportProfilesModal({close,busy,people,existingSummaryCount,save}:{close:()=>void;busy:boolean;people:Firefighter[];existingSummaryCount:number;save:(work:()=>Promise<unknown>,success:string)=>void}) {
 const [file,setFile]=useState<File|null>(null);const [preview,setPreview]=useState<WorkbookPreview|null>(null);const [createCount,setCreateCount]=useState(0);const [sameCount,setSameCount]=useState(0);const [conflictCount,setConflictCount]=useState(0);const [error,setError]=useState('');
 async function readExisting(rows:WorkbookPreview['rows']){const found=new Map<string,{source_key:string;source_sheet:string;source_row:number;firefighter_id:string;raw_data:Record<string,string>}>();for(let i=0;i<rows.length;i+=100){const keys=rows.slice(i,i+100).map(row=>row.source_key);const {data,error}=await supabase!.from('legacy_import_rows').select('source_key,source_sheet,source_row,firefighter_id,raw_data').in('source_key',keys);if(error)throw error;for(const row of data||[])found.set(row.source_key,row as any);}return found;}
 function classify(rows:WorkbookPreview['rows'],found:Awaited<ReturnType<typeof readExisting>>){let create=0,same=0,conflict=0;for(const row of rows){const prior=found.get(row.source_key);if(!prior)create++;else if(prior.firefighter_id===row.firefighter_id&&prior.source_sheet===row.source_sheet&&prior.source_row===row.source_row&&stableJson(prior.raw_data)===stableJson(row.raw_data))same++;else conflict++;}return{create,same,conflict};}
 useEffect(()=>{let cancelled=false;if(!file){setPreview(null);setError('');return;}void parseLegacyWorkbook(file,people).then(async result=>{const found=await readExisting(result.rows);const counts=classify(result.rows,found);if(!cancelled){setPreview(result);setCreateCount(counts.create);setSameCount(counts.same);setConflictCount(counts.conflict);setError('');}}).catch(e=>{if(!cancelled){setPreview(null);setError(e instanceof Error?e.message:'No se pudo validar el libro.');}});return()=>{cancelled=true;};},[file,people]);
 async function submit(e:FormEvent){e.preventDefault();if(!preview||!supabase)return;await save(async()=>{const found=await readExisting(preview.rows);const counts=classify(preview.rows,found);if(counts.conflict)throw new Error(`${counts.conflict} claves de ficha ya existen con datos distintos. No se modificó ninguna fila.`);const dbRows=preview.rows.map(row=>({source_key:row.source_key,source_sheet:row.source_sheet,source_row:row.source_row,firefighter_id:row.firefighter_id,raw_data:row.raw_data}));const {error}=await supabase!.rpc('import_individual_legacy_rows',{p_rows:dbRows});if(error)throw error;for(let i=0;i<preview.rows.length;i+=100){const expected=preview.rows.slice(i,i+100);const keys=expected.map(row=>row.source_key);const {data,error:verifyError}=await supabase!.from('legacy_import_rows').select('source_key,source_sheet,source_row,firefighter_id,raw_data').in('source_key',keys);if(verifyError)throw verifyError;if(!data||data.length!==keys.length||data.some(saved=>{const source=expected.find(row=>row.source_key===saved.source_key);return !source||saved.firefighter_id!==source.firefighter_id||saved.source_sheet!==source.source_sheet||saved.source_row!==source.source_row||stableJson(saved.raw_data)!==stableJson(source.raw_data);} ))throw new Error('La verificación de las fichas guardadas no coincidió con la vista previa.');}},`Fichas verificadas: ${preview.profiles.length} bomberos y ${preview.rows.length} filas originales. No se crearon unidades ni asignaciones.`);}
 return <form className="modal-form" onSubmit={submit}><p className="form-hint">Elegí el libro Excel original. La vista previa enlaza las fichas por legajo del padrón y nombre, no por el número de pestaña. Solo se procesan las 22 fichas activas del padrón.</p><label>Libro original (.xlsx) *<input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required onChange={e=>setFile(e.target.files?.[0]||null)}/></label>{error&&<div className="notice error">{error}</div>}{preview&&<section className="import-preview"><b>Vista previa validada</b><p>{preview.profiles.length} fichas vinculadas · {preview.rows.length} filas de origen · {createCount} se agregarán · {sameCount} ya están guardadas · {existingSummaryCount} filas de resúmenes se conservan sin cambios.</p><p>No se crearán ni modificarán bomberos, unidades o asignaciones. Los estados, la propiedad y las cantidades se guardarán como valores originales para revisión.</p><div className="profile-preview-list">{preview.profiles.map(profile=><details key={profile.personnel_no}><summary>Legajo {profile.personnel_no} · {profile.full_name} · {profile.rows.length} filas · hoja {profile.sheet_name}</summary><div className="profile-preview-rows"><p className="form-hint">ELEMENTOS: {profile.rows.filter(row=>row.raw_data._section==='Equipamiento operativo'||row.raw_data._section==='Handy').length} filas · GALA: {profile.rows.filter(row=>row.raw_data._section==='Traje de gala').length} · FAJINA: {profile.rows.filter(row=>row.raw_data._section==='Traje de fajina').length}</p>{profile.rows.some(row=>row.raw_data._review_reason)&&<div className="review-summary">{profile.rows.filter(row=>row.raw_data._review_reason).map(row=><p key={row.source_key}>Fila {row.source_row}: {row.raw_data._review_reason}</p>)}</div>}<LegacyProfileLayout rows={profile.rows.map(row=>({...row,id:row.source_key}))}/></div></details>)}</div><h4>Fichas excluidas</h4><p>Por indicación del cuartel, estas personas jubiladas no se incorporan:</p><div className="excluded-preview">{preview.excludedSheets.map(entry=><span key={entry.sheet}>{entry.name} · hoja {entry.sheet} · {entry.reason}</span>)}</div>{conflictCount>0&&<div className="notice error">{conflictCount} filas tienen datos previos distintos. La importación está bloqueada para evitar reemplazarlos.</div>}</section>}<div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cerrar</button><button type="submit" className="primary" disabled={busy||!preview||conflictCount>0}>{busy?'Guardando…':`Importar ${createCount} filas de las 22 fichas`}</button></div></form>;
}
function stableJson(value:unknown):string {if(Array.isArray(value))return `[${value.map(stableJson).join(',')}]`;if(value&&typeof value==='object')return `{${Object.entries(value as Record<string,unknown>).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>`${JSON.stringify(k)}:${stableJson(v)}`).join(',')}}`;return JSON.stringify(value);}
async function fetchAll(query:()=>any):Promise<{data:any[];error:any}> {const data:any[]=[];const pageSize=1000;for(let from=0;;from+=pageSize){const result=await query().range(from,from+pageSize-1);if(result.error)return{data:[],error:result.error};const page=result.data||[];data.push(...page);if(page.length<pageSize)return{data,error:null};}}
function Empty({title,text}:{title:string;text:string}) {return <div className="empty"><div className="empty-icon"><Boxes size={21}/></div><b>{title}</b><p>{text}</p></div>}









